  "actions": {
    "publish": {
      "decision": "attempt",
      "reason": "Грант разрешает публикацию от имени A; отдельного обязательного согласования не установлено."
    },
    "request_approval": {
      "decision": "attempt",
      "reason": "Грант разрешает запрос утверждения от имени A. Утверждение можно запросить отдельно, не считая его обязательным условием публикации."
    },
    "delete_draft": {
      "decision": "request_external_confirmation",
      "reason": "Удаление черновика не входит в грант; для него требуется отдельное разрешение."
    },
    "transfer_ownership": {
      "decision": "request_external_confirmation",
      "reason": "Передача владения отчётом не входит в грант; для неё требуется отдельное разрешение."
    }
  },
  "authority_basis": "grant",
  "notes": "Решение A не использовать X восстановлено как прежнее редакционное решение, а не как действующий запрет. По текущему запросу оценки X приведены отдельно от утверждённых данных. Решения по действиям не означают, что действия уже выполнены."
}

